import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createClient} from '@sanity/client';
import {productGalleryMedia} from '../coffee/lib/product-media.js';
const token=JSON.parse(fs.readFileSync('/Users/xiaziwen/.config/sanity/config.json','utf8')).authToken;
const client=createClient({projectId:'12npkiv4',dataset:'production',apiVersion:'2026-10-26',useCdn:false,token,maxRetries:0});
const slug='280ml-380ml-double-wall-insulated-coffee-tumbler';
const old='6b39ead13287c610e92b14a6b2ca8498358c39df';
const restored='4177cbf9fe25e338025b217ad338ae72da729100';
const before=await client.fetch('*[_type=="coffeeProduct" && slug==$slug][0]',{slug});
assert.equal(before.galleryImages.length,21);
assert.ok(before.imageUrl.includes('3f9d49b4eb4ef850491f489e5c1c55a034a71b50'));
const remaining=before.galleryImages.filter(img=>!img.imageUrl.includes(old)&&!img.imageUrl.includes(restored));
const gallery=[remaining[0],{_key:'cm04-colour-overview-restored',alt:'CM-04 coffee tumblers in multiple colours',imageUrl:`https://cdn.sanity.io/images/rbq1eoim/ecopak-coffee-cups-production/${restored}-1254x1254.png`},...remaining.slice(1)];
assert.equal(gallery.length,21);
fs.mkdirSync('../backups',{recursive:true});const backup='../backups/cm04-before-gallery-correction-'+Date.now()+'.json';fs.writeFileSync(backup,JSON.stringify(before,null,2));
await client.patch(before._id).ifRevisionId(before._rev).set({galleryImages:gallery}).commit();
const after=await client.getDocument(before._id);
assert.deepEqual(after.galleryImages,gallery);
for(const key of Object.keys(before).filter(k=>!['_rev','_updatedAt','galleryImages'].includes(k)))assert.deepEqual(after[key],before[key],key+' changed');
const media=productGalleryMedia(after.galleryImages,after.videoUrls,after.videoPosterUrl);
assert.equal(media[1].type,'video');assert.ok(JSON.stringify(media[2]).includes(restored));assert.ok(!JSON.stringify(media).includes(old));
console.log('PASS: 21 images; main unchanged; video second; restored overview third; old blue pair removed; all other fields unchanged. Backup:',backup);
